56	function oneLine(strings: TemplateStringsArray, ...values: unknown[]): string {
57	  let result = '';
58	  for (let i = 0; i < strings.length; i++) {
59	    result += strings[i];
60	    if (i < values.length) {
61	      result += String(values[i]);
62	    }
63	  }
64	  return result.replace(/\s+/g, ' ').trim();
65	}
