31	interface ToolGroupMessageProps {
32	  item: HistoryItem | HistoryItemWithoutId;
33	  toolCalls: IndividualToolCallDisplay[];
34	  availableTerminalHeight?: number;
35	  terminalWidth: number;
36	  onShellInputSubmit?: (input: string) => void;
37	  borderTop?: boolean;
38	  borderBottom?: boolean;
39	  isExpandable?: boolean;
40	}
41	
42	// Main component renders the border and maps the tools using ToolMessage
43	const TOOL_MESSAGE_HORIZONTAL_MARGIN = 4;
44	
45	export const ToolGroupMessage: React.FC<ToolGroupMessageProps> = ({
46	  item,
47	  toolCalls: allToolCalls,
48	  availableTerminalHeight,
49	  terminalWidth,
50	  borderTop: borderTopOverride,
51	  borderBottom: borderBottomOverride,
52	  isExpandable,
53	}) => {
54	  // Filter out tool calls that should be hidden (e.g. in-progress Ask User, or Plan Mode operations).
55	  const toolCalls = useMemo(
56	    () =>
57	      allToolCalls.filter(
58	        (t) =>
59	          !shouldHideToolCall({
60	            displayName: t.name,
61	            status: t.status,
62	            approvalMode: t.approvalMode,
63	            hasResultDisplay: !!t.resultDisplay,
64	          }),
65	      ),
66	    [allToolCalls],
67	  );
68	
69	  const config = useConfig();
70	  const {
71	    constrainHeight,
72	    activePtyId,
73	    embeddedShellFocused,
74	    backgroundShells,
75	    pendingHistoryItems,
76	  } = useUIState();
77	  const isAlternateBuffer = useAlternateBuffer();
78	
79	  const { borderColor, borderDimColor } = useMemo(
80	    () =>
81	      getToolGroupBorderAppearance(
82	        item,
83	        activePtyId,
84	        embeddedShellFocused,
85	        pendingHistoryItems,
86	        backgroundShells,
87	      ),
88	    [
89	      item,
90	      activePtyId,
91	      embeddedShellFocused,
92	      pendingHistoryItems,
93	      backgroundShells,
94	    ],
95	  );
96	
97	  // We HIDE tools that are still in pre-execution states (Confirming, Pending)
98	  // from the History log. They live in the Global Queue or wait for their turn.
99	  // Only show tools that are actually running or finished.
100	  // We explicitly exclude Pending and Confirming to ensure they only
101	  // appear in the Global Queue until they are approved and start executing.
102	  const visibleToolCalls = useMemo(
103	    () =>
104	      toolCalls.filter((t) => {
105	        const displayStatus = mapCoreStatusToDisplayStatus(t.status);
106	        return (
107	          displayStatus !== ToolCallStatus.Pending &&
108	          displayStatus !== ToolCallStatus.Confirming
109	        );
110	      }),
111	
112	    [toolCalls],
113	  );
114	
115	  const staticHeight = /* border */ 2;
116	
117	  let countToolCallsWithResults = 0;
118	  for (const tool of visibleToolCalls) {
119	    if (tool.resultDisplay !== undefined && tool.resultDisplay !== '') {
120	      countToolCallsWithResults++;
121	    }
122	  }
123	  const countOneLineToolCalls =
124	    visibleToolCalls.length - countToolCallsWithResults;
125	  const availableTerminalHeightPerToolMessage = availableTerminalHeight
126	    ? Math.max(
127	        Math.floor(
128	          (availableTerminalHeight - staticHeight - countOneLineToolCalls) /
129	            Math.max(1, countToolCallsWithResults),
130	        ),
131	        1,
132	      )
133	    : undefined;
134	
135	  const contentWidth = terminalWidth - TOOL_MESSAGE_HORIZONTAL_MARGIN;
