19	/**
20	 * Transforms `ToolCall` objects into `HistoryItemToolGroup` objects for UI
21	 * display. This is a pure projection layer and does not track interaction
22	 * state.
23	 */
24	export function mapToDisplay(
25	  toolOrTools: ToolCall[] | ToolCall,
26	  options: {
27	    borderTop?: boolean;
28	    borderBottom?: boolean;
29	    borderColor?: string;
30	    borderDimColor?: boolean;
31	  } = {},
32	): HistoryItemToolGroup {
33	  const toolCalls = Array.isArray(toolOrTools) ? toolOrTools : [toolOrTools];
34	  const { borderTop, borderBottom, borderColor, borderDimColor } = options;
35	
36	  const toolDisplays = toolCalls.map((call): IndividualToolCallDisplay => {
37	    let description: string;
38	    let renderOutputAsMarkdown = false;
39	
40	    const displayName = call.tool?.displayName ?? call.request.name;
41	
42	    if (call.status === CoreToolCallStatus.Error) {
43	      description = JSON.stringify(call.request.args);
44	    } else {
45	      description = call.invocation.getDescription();
46	      renderOutputAsMarkdown = call.tool.isOutputMarkdown;
47	    }
48	
49	    const baseDisplayProperties = {
50	      callId: call.request.callId,
51	      name: displayName,
52	      description,
53	      renderOutputAsMarkdown,
54	    };
55	
56	    let resultDisplay: ToolResultDisplay | undefined = undefined;
57	    let confirmationDetails: SerializableConfirmationDetails | undefined =
58	      undefined;
59	    let outputFile: string | undefined = undefined;
60	    let ptyId: number | undefined = undefined;
61	    let correlationId: string | undefined = undefined;
62	    let progressMessage: string | undefined = undefined;
63	    let progress: number | undefined = undefined;
64	    let progressTotal: number | undefined = undefined;
65	
66	    switch (call.status) {
67	      case CoreToolCallStatus.Success:
68	        resultDisplay = call.response.resultDisplay;
69	        outputFile = call.response.outputFile;
70	        break;
71	      case CoreToolCallStatus.Error:
72	      case CoreToolCallStatus.Cancelled:
73	        resultDisplay = call.response.resultDisplay;
74	        break;
75	      case CoreToolCallStatus.AwaitingApproval:
76	        correlationId = call.correlationId;
77	        // Pass through details. Context handles dispatch (callback vs bus).
78	        confirmationDetails = call.confirmationDetails;
79	        break;
80	      case CoreToolCallStatus.Executing:
81	        resultDisplay = call.liveOutput;
82	        ptyId = call.pid;
83	        progressMessage = call.progressMessage;
84	        progress = call.progress;
85	        progressTotal = call.progressTotal;
86	        break;
87	      case CoreToolCallStatus.Scheduled:
88	      case CoreToolCallStatus.Validating:
89	        break;
90	      default: {
91	        const exhaustiveCheck: never = call;
92	        debugLogger.warn(
93	          `Unhandled tool call status in mapper: ${
94	            (exhaustiveCheck as ToolCall).status
95	          }`,
96	        );
97	        break;
98	      }
99	    }
100	
101	    return {
102	      ...baseDisplayProperties,
103	      status: call.status,
104	      resultDisplay,
105	      confirmationDetails,
106	      outputFile,
107	      ptyId,
108	      correlationId,
109	      progressMessage,
110	      progress,
111	      progressTotal,
112	      approvalMode: call.approvalMode,
113	      originalRequestName: call.request.originalRequestName,
114	    };
115	  });
116	
117	  return {
118	    type: 'tool_group',
119	    tools: toolDisplays,
120	    borderTop,
121	    borderBottom,
122	    borderColor,
123	    borderDimColor,
124	  };
125	}
