25	export const useLoadingIndicator = ({
26	  streamingState,
27	  shouldShowFocusHint,
28	  retryStatus,
29	  loadingPhrasesMode,
30	  customWittyPhrases,
31	}: UseLoadingIndicatorProps) => {
32	  const [timerResetKey, setTimerResetKey] = useState(0);
33	  const isTimerActive = streamingState === StreamingState.Responding;
34	
35	  const elapsedTimeFromTimer = useTimer(isTimerActive, timerResetKey);
36	
37	  const isPhraseCyclingActive = streamingState === StreamingState.Responding;
38	  const isWaiting = streamingState === StreamingState.WaitingForConfirmation;
39	  const currentLoadingPhrase = usePhraseCycler(
40	    isPhraseCyclingActive,
41	    isWaiting,
42	    shouldShowFocusHint,
43	    loadingPhrasesMode,
44	    customWittyPhrases,
45	  );
46	
47	  const [retainedElapsedTime, setRetainedElapsedTime] = useState(0);
48	  const prevStreamingStateRef = useRef<StreamingState | null>(null);
49	
50	  useEffect(() => {
51	    if (
52	      prevStreamingStateRef.current === StreamingState.WaitingForConfirmation &&
53	      streamingState === StreamingState.Responding
54	    ) {
55	      setTimerResetKey((prevKey) => prevKey + 1);
56	      setRetainedElapsedTime(0); // Clear retained time when going back to responding
57	    } else if (
58	      streamingState === StreamingState.Idle &&
59	      prevStreamingStateRef.current === StreamingState.Responding
60	    ) {
61	      setTimerResetKey((prevKey) => prevKey + 1); // Reset timer when becoming idle from responding
62	      setRetainedElapsedTime(0);
63	    } else if (streamingState === StreamingState.WaitingForConfirmation) {
64	      // Capture the time when entering WaitingForConfirmation
65	      // elapsedTimeFromTimer will hold the last value from when isTimerActive was true.
66	      setRetainedElapsedTime(elapsedTimeFromTimer);
67	    }
68	
69	    prevStreamingStateRef.current = streamingState;
70	  }, [streamingState, elapsedTimeFromTimer]);
71	
72	  const retryPhrase = retryStatus
73	    ? `Trying to reach ${getDisplayString(retryStatus.model)} (Attempt ${retryStatus.attempt + 1}/${retryStatus.maxAttempts})`
74	    : null;
75	
76	  return {
77	    elapsedTime:
78	      streamingState === StreamingState.WaitingForConfirmation
79	        ? retainedElapsedTime
80	        : elapsedTimeFromTimer,
81	    currentLoadingPhrase: retryPhrase || currentLoadingPhrase,
82	  };
83	};
